const GLOSSARY_DATA=[{"week":"W7","category":"基础","term":"Temporal data","chinese":"时间数据","concept":"带有时刻、日期或有效时间段的数据。","purpose":"描述事实何时发生、何时有效或数据库何时知道它。","relation":"是 temporal database 与 time series 的共同上位概念。","example":"天气观测包含 obsdate；员工职位包含有效起止日期。"},{"week":"W7","category":"基础","term":"Historical data / Long data","chinese":"历史数据／长时间跨度数据","concept":"长期保存的过去记录，而不只是当前快照。","purpose":"用于趋势、审计和回溯分析。","relation":"Big data 强调体量、速度、种类；long data 强调时间跨度。","example":"比较企业过去 20 年的销售变化。"},{"week":"W7","category":"数据库","term":"Temporal DBMS","chinese":"时间数据库管理系统","concept":"内建时间维度支持的 DBMS，可按时间存储、查询和更新。","purpose":"直接表达过去、现在、未来及时间推理，减少应用层手写逻辑。","relation":"普通 DBMS 通常只保存当前快照；temporal DBMS 提供 temporal SQL。","example":"查询某员工在 2025-03-01 的职位。"},{"week":"W7","category":"数据库","term":"Conventional database","chinese":"传统／非时间数据库","concept":"主要表示现实世界当前状态的数据库。","purpose":"适合当前值事务，但历史通常需应用自行维护。","relation":"与 temporal database 对比。","example":"UPDATE 职位后旧职位被覆盖。"},{"week":"W7","category":"时间类型","term":"Instant / Point","chinese":"时刻／时间点","concept":"时间轴上的单一位置。","purpose":"给事件或观测加精确时间标记。","relation":"与 interval 的长度、period 的有界区间不同。","example":"2026-10-23 09:30:00。"},{"week":"W7","category":"时间类型","term":"Interval","chinese":"时间间隔／时长","concept":"只有长度、没有固定时间轴位置的持续量。","purpose":"进行时间加减或表示持续时间。","relation":"INTERVAL '2 hours' 是时长；period 有具体起止。","example":"timestamp + INTERVAL '30 minutes'。"},{"week":"W7","category":"时间类型","term":"Period","chinese":"时间段","concept":"由同类型的开始和结束边界确定的锚定区间。","purpose":"表示事实在现实中的有效范围。","relation":"通常采用半开区间 [start,end)。","example":"合同从 1 月 1 日有效到 2 月 1 日前。"},{"week":"W7","category":"时间类型","term":"DATE","chinese":"日期类型","concept":"只表示年、月、日，不含一天内时间。","purpose":"存生日、账期日期等日粒度事实。","relation":"比 TIMESTAMP 粒度低；与 TIME 组合可形成完整时间点。","example":"DATE '2026-10-23'。"},{"week":"W7","category":"时间类型","term":"TIME","chinese":"时钟时间类型","concept":"表示时、分、秒但通常没有日期。","purpose":"表示每天的时间或班次时刻。","relation":"单独 TIME 不能唯一定位跨日期的事件。","example":"TIME '17:00:00'。"},{"week":"W7","category":"时间类型","term":"TIMESTAMP","chinese":"时间戳","concept":"日期与时钟时间的组合，可带小数秒和时区语义。","purpose":"给事件排序、过滤和连接。","relation":"TIMESTAMP WITH TIME ZONE 与无时区版本语义不同。","example":"TIMESTAMP '2026-10-23 17:00:00'。"},{"week":"W7","category":"时间类型","term":"Time zone","chinese":"时区","concept":"把本地时钟时间映射到全球统一时间轴的规则。","purpose":"避免跨地区记录比较错误。","relation":"时区不同于 UTC offset；夏令时会改变 offset。","example":"悉尼 17:00 转为 UTC 后再比较纽约事件。"},{"week":"W7","category":"时间类型","term":"Temporal granularity / Resolution","chinese":"时间粒度／分辨率","concept":"时间值能区分的最小单位，如日、秒、毫秒。","purpose":"决定能否区分相邻事件和窗口边界。","relation":"粒度过粗可能产生并列 timestamp。","example":"日粒度不能区分同一天两笔交易的先后。"},{"week":"W7","category":"时间语义","term":"User-defined time","chinese":"用户定义时间","concept":"数据库不解释其时间语义的普通日期／时间属性。","purpose":"由应用决定字段意义。","relation":"不同于 DBMS 认识的 valid time 或 transaction time。","example":"birthdate 只是普通 DATE 列。"},{"week":"W7","category":"时间语义","term":"Valid time / Fact time / Application time","chinese":"有效时间／事实时间／应用时间","concept":"事实在现实世界中为真的时间。","purpose":"回答“现实中什么时候成立”。","relation":"可被追溯修正；SQL:2011 称 application time。","example":"合同 1 月生效，即使 2 月才录入。"},{"week":"W7","category":"时间语义","term":"Transaction time / Database time / System time","chinese":"事务时间／数据库时间／系统时间","concept":"某版本何时被数据库保存和可见。","purpose":"支持审计、回滚和回答“数据库何时知道”。","relation":"只随系统时间向前；SQL:2011 称 system time。","example":"数据库 2 月 3 日记录合同。"},{"week":"W7","category":"时间语义","term":"Bitemporal","chinese":"双时间","concept":"同时保存 valid time 与 transaction time。","purpose":"既追踪现实变化，又追踪数据库认识的变化。","relation":"等于两条时间轴的组合。","example":"3 月发现 1 月工资录错，可保留原录入和修正历史。"},{"week":"W7","category":"表类型","term":"Temporal table","chinese":"时间表","concept":"包含 DBMS 认可的时间列并支持时间语义查询的表。","purpose":"自动或规范地维护历史版本。","relation":"可进一步分 valid-time、transaction-time、bitemporal。","example":"Policy 表包含 Validity period。"},{"week":"W7","category":"表类型","term":"Valid-time table","chinese":"有效时间表","concept":"带有效时间维度的表。","purpose":"记录现实事实在何时成立。","relation":"只含 valid time，不一定记录数据库修改历史。","example":"职位记录带 start_date/end_date。"},{"week":"W7","category":"表类型","term":"Transaction-time table","chinese":"事务时间表","concept":"带数据库系统时间维度的表。","purpose":"保存每个数据库版本的可见区间。","relation":"只含 transaction time，不一定知道现实有效期。","example":"系统自动保存 UPDATE 前的旧行。"},{"week":"W7","category":"表类型","term":"Nontemporal table","chinese":"非时间表","concept":"没有 valid-time 或 transaction-time 维度的普通表。","purpose":"保存当前状态或普通事件属性。","relation":"与 temporal table 相对。","example":"只存当前地址的 Customer 表。"},{"week":"W7","category":"表类型","term":"Semi-temporal table","chinese":"半时间表","concept":"只记录当前事实从何时开始有效，例如 since。","purpose":"低成本回答“当前状态持续多久”。","relation":"通常不能恢复完整历史。","example":"Employee(city,since) 只保留现城市及开始日期。"},{"week":"W7","category":"边界","term":"Half-open interval [start,end)","chinese":"左闭右开区间","concept":"包含开始、不包含结束的时间段。","purpose":"让相邻区间无重叠、无缝衔接。","relation":"BETWEEN 通常两端包含，可能导致边界重复。","example":"[09:00,10:00) 与 [10:00,11:00) 不重复。"},{"week":"W7","category":"当前值","term":"NOW / UC (Until Changed)","chinese":"当前／直到改变","concept":"表示事实当前有效且结束时间尚未发生。","purpose":"建模开放结束的当前记录。","relation":"PostgreSQL now 是事务开始时刻；开放结束常用 infinity。","example":"现任职位有效至 infinity。"},{"week":"W7","category":"当前值","term":"Max-timestamp / Infinity","chinese":"最大时间戳／无穷","concept":"用极大日期或 infinity 表示开放结束。","purpose":"使范围比较保持普通逻辑。","relation":"比 NULL 更容易查询，但必须约定语义。","example":"end_date='9999-12-31' 或 'infinity'。"},{"week":"W7","category":"当前值","term":"NULL","chinese":"空值／未知值","concept":"SQL 中表示缺失或未知，而非普通数值。","purpose":"表达未知数据。","relation":"与任何普通比较结果为 UNKNOWN，不能直接当“永远”。","example":"end_date IS NULL，而不是 end_date > today。"},{"week":"W7","category":"查询语义","term":"Current query","chinese":"当前查询","concept":"只询问现在有效的数据。","purpose":"回答当前库存、当前职位。","relation":"是 temporal statement 的一种；不恢复过去。","example":"CURRENT VALIDTIME SELECT ...。"},{"week":"W7","category":"查询语义","term":"Sequenced query","chinese":"序列化时间查询","concept":"按每个有效时刻的时间语义执行关系运算。","purpose":"得到随时间变化的答案。","relation":"与 nonsequenced 的“把时间列当普通数据”不同。","example":"求每个时期各部门预算总额。"},{"week":"W7","category":"查询语义","term":"Nonsequenced query","chinese":"非序列时间查询","concept":"忽略内建时间语义，将时间属性当普通列处理。","purpose":"执行跨历史版本的普通统计或筛选。","relation":"不自动对齐有效区间。","example":"统计历史上一共出现过多少职位记录。"},{"week":"W7","category":"SQL","term":"CURRENT_DATE / CURRENT_TIME","chinese":"当前日期／当前时间","concept":"由数据库系统给出的当前日期或时间常量。","purpose":"构造相对当前时刻的过滤。","relation":"值受 DBMS 与事务语义影响。","example":"WHERE obsdate < CURRENT_DATE。"},{"week":"W7","category":"SQL","term":"EXTRACT","chinese":"时间分量提取函数","concept":"从日期或时间戳中取 YEAR、MONTH 等字段。","purpose":"用于按年/月分组或过滤。","relation":"它返回分量，不会自动聚合。","example":"EXTRACT(YEAR FROM ts)=2026。"},{"week":"W7","category":"SQL","term":"INTERVAL arithmetic","chinese":"时间间隔运算","concept":"用 INTERVAL 对时间点做加减。","purpose":"计算截止时间和滚动范围。","relation":"不要把字符串或整数直接当带单位时长。","example":"ts + INTERVAL '36 hours'。"},{"week":"W7","category":"SQL","term":"BETWEEN","chinese":"区间比较谓词","concept":"判断值是否位于两个端点之间，通常包含两端。","purpose":"写简洁范围过滤。","relation":"连续时间窗口更安全地写 >= start AND < end。","example":"x BETWEEN 1 AND 3 包含 1 和 3。"},{"week":"W7","category":"标准","term":"SQL:2011 PERIOD FOR","chinese":"SQL:2011 时间段定义","concept":"把物理 start/end 列声明为一个概念 period。","purpose":"让 DBMS 理解 application/system time。","relation":"它是表元数据分组，并非普遍的新标量类型。","example":"PERIOD FOR EPeriod(EStart,EEnd)。"},{"week":"W7","category":"分析","term":"Temporal aggregation","chinese":"时间聚合","concept":"在每个时间片上计算当时有效记录的聚合值。","purpose":"产生随时间变化的 SUM/COUNT/AVG。","relation":"普通 GROUP BY 只给静态组结果；时间聚合需切分变化点。","example":"每个时期计算部门有效项目预算。"},{"week":"W7","category":"PostgreSQL","term":"Range type / DATERANGE","chinese":"范围类型／日期范围","concept":"把上下界作为单个区间值保存的 PostgreSQL 类型。","purpose":"直接支持包含、重叠、交并差和范围索引。","relation":"比两个独立 start/end 列更接近 period 语义。","example":"'[2010-01-01,2011-01-01)'::daterange。"},{"week":"W7","category":"PostgreSQL","term":"GiST (Generalized Search Tree)","chinese":"广义搜索树索引","concept":"支持可扩展谓词的索引框架，适合范围和空间对象。","purpose":"加速 overlap、contains 等不能靠普通排序键充分表达的查询。","relation":"B-tree 适合标量顺序；GiST 可索引区间关系。","example":"CREATE INDEX ... USING gist(valid_period)。"},{"week":"W7","category":"PostgreSQL","term":"Overlap operator &&","chinese":"重叠运算符","concept":"判断两个 PostgreSQL range 是否有共同部分。","purpose":"查时间冲突或连接同时有效记录。","relation":"条件等价思想为 a.start < b.end AND b.start < a.end。","example":"预订区间 && 已有预订区间。"},{"week":"W7","category":"PostgreSQL","term":"upper_inf()","chinese":"上界无穷检查函数","concept":"判断 range 的上界是否为正无穷。","purpose":"找到当前仍开放的时间段。","relation":"不同于 upper(range)，它返回布尔值。","example":"WHERE upper_inf(valid_period)。"},{"week":"W7","category":"PostgreSQL","term":"Range union / intersection / difference","chinese":"范围并／交／差","concept":"对可合并范围执行 +、*、- 运算。","purpose":"组合或比较有效区间。","relation":"union 通常要求范围相交或相邻。","example":"'[2010,2013)' * '[2012,2015)' 得 [2012,2013)。"},{"week":"W7","category":"时间序列","term":"Time series","chinese":"时间序列","concept":"按时间先后排列的一系列观测值。","purpose":"分析趋势、周期、变化和预测。","relation":"属于 temporal data，通常强调离散时间点序列。","example":"每小时温度读数。"},{"week":"W7","category":"流程","term":"Data ingress","chinese":"数据进入／摄取","concept":"从文件、数据库或网页把数据引入分析流程。","purpose":"建立时间序列处理的输入端。","relation":"后续还有 storage、analysis、visualisation。","example":"读取 CSV 并解析 timestamp。"},{"week":"W7","category":"存储","term":"Point-based representation","chinese":"点式表示","concept":"每个观测时间点单独占一行。","purpose":"便于过滤、更新、B-tree 索引和关系查询。","relation":"与一行保存数组的 sequence-based 表示对比。","example":"(station,ts,temp) 每分钟一行。"},{"week":"W7","category":"存储","term":"Sequence-based representation","chinese":"序列式表示","concept":"一行保存一段有序时间点或值数组。","purpose":"减少行数并对整段序列操作。","relation":"必须维护顺序、数组长度和时间值对齐。","example":"一天一行保存 timestamps[] 与 temperatures[]。"},{"week":"W7","category":"关系模型","term":"Atomic value","chinese":"原子值","concept":"关系表一个单元中不可再分的单值。","purpose":"满足传统关系模型的基本字段假设。","relation":"数组是复合值，因此 sequence-based 表示偏离严格 1NF。","example":"单个 temperature=22.5。"},{"week":"W7","category":"关系模型","term":"1NF (First Normal Form)","chinese":"第一范式","concept":"每个属性位置保存单一原子值的关系设计原则。","purpose":"让关系操作和约束保持简单一致。","relation":"数组列或嵌套表通常被视为超出严格 1NF。","example":"把多个温度拆成多行符合 1NF。"},{"week":"W7","category":"数据库","term":"Append-only","chinese":"仅追加写入","concept":"主要插入新事件，不覆盖旧事件。","purpose":"天然保留历史并简化审计。","relation":"与 UPDATE 当前行不同。","example":"传感器每来一条观测就 INSERT。"},{"week":"W7","category":"数据库","term":"B-tree index","chinese":"B 树索引","concept":"按可排序键组织的通用索引。","purpose":"加速等值和范围查询。","relation":"适合单一 timestamp；复杂 range overlap 常用 GiST。","example":"CREATE INDEX ON observations(ts)。"},{"week":"W7","category":"分析","term":"OLAP","chinese":"联机分析处理","concept":"面向大量数据的筛选、分组和聚合分析。","purpose":"总结时间序列和仓库数据。","relation":"与高频小事务 OLTP 侧重点不同。","example":"按站点和月份计算 AVG(temp)。"},{"week":"W7","category":"建模","term":"Dimension table","chinese":"维度表","concept":"保存描述性实体属性供事实数据连接。","purpose":"给观测增加站点、地区等上下文。","relation":"时间序列表常是事实表，维度表较稳定。","example":"Observations JOIN Station ON station_id。"},{"week":"W7","category":"数组","term":"Array","chinese":"数组","concept":"一个字段内按位置保存多个同类型元素。","purpose":"实现序列式时间数据。","relation":"顺序是语义的一部分；平行数组必须对齐。","example":"temperature FLOAT[]。"},{"week":"W7","category":"数组","term":"array_agg()","chinese":"数组聚合函数","concept":"把多行值收集成一个数组。","purpose":"从 point-based 转为 sequence-based。","relation":"内部 ORDER BY 才能保证数组顺序。","example":"array_agg(temp ORDER BY ts)。"},{"week":"W7","category":"数组","term":"UNNEST","chinese":"数组展开操作","concept":"把一个数组的元素转换为多行。","purpose":"从 sequence-based 恢复为关系行。","relation":"多个数组分别展开可能产生错配或笛卡尔扩张。","example":"SELECT unnest(temperatures)。"},{"week":"W7","category":"索引","term":"GIN (Generalized Inverted Index)","chinese":"广义倒排索引","concept":"为数组、全文等多值内容建立倒排项到行的映射。","purpose":"加速数组包含或元素搜索。","relation":"GiST 擅长范围/空间关系；GIN 擅长成员集合查询。","example":"CREATE INDEX ... USING gin(tags)。"},{"week":"W7","category":"JSON","term":"Schema-on-read","chinese":"读时模式","concept":"数据写入时保持灵活，读取时才解释结构。","purpose":"适配结构可变的 JSON。","relation":"灵活不等于无模式；查询仍依赖稳定字段含义。","example":"读取 values[].date 时应用日期类型。"},{"week":"W7","category":"JSON","term":"Data-as-field-name anti-pattern","chinese":"把数据当字段名的反模式","concept":"用日期等实例值充当 JSON key。","purpose":"虽然便于对象查找，却破坏范围查询和字段索引。","relation":"字段名应表达 schema，日期应作为 value。","example":"错误：{'2026-01-01':100}；正确：{'date':'2026-01-01','sales':100}。"},{"week":"W8","category":"数据类型","term":"Structured data","chinese":"结构化数据","concept":"遵循固定字段、类型和表模式的数据。","purpose":"可直接由关系数据库存储与查询。","relation":"与 semi-structured、unstructured 构成结构程度谱系。","example":"Customer(id,name,age) 表。"},{"week":"W8","category":"数据类型","term":"Semi-structured data","chinese":"半结构化数据","concept":"有键、标签或层级，但记录结构可变化的数据。","purpose":"保留部分机器可读结构同时允许灵活字段。","relation":"JSON/XML 通常属于半结构化，不是纯文本式非结构化。","example":"两个 JSON 文档可有不同可选字段。"},{"week":"W8","category":"数据类型","term":"Unstructured data","chinese":"非结构化数据","concept":"不能直接用固定行列完整表达内容的数据。","purpose":"需要预处理和特征提取后才能被传统分析或 ML 使用。","relation":"并非完全没有内部结构。","example":"自然语言、照片、视频。"},{"week":"W8","category":"文本","term":"NLP (Natural Language Processing)","chinese":"自然语言处理","concept":"让计算机分析、理解或生成自然语言的方法集合。","purpose":"从文本提取语义、实体、情感或分类特征。","relation":"tokenisation 与 embedding 是常见 NLP 管线环节。","example":"判断评论是正面还是负面。"},{"week":"W8","category":"文本","term":"Semantic analysis","chinese":"语义分析","concept":"分析文本表达的含义，而不仅是字符或词频。","purpose":"处理歧义、关系和意图。","relation":"比单纯关键词计数更关注上下文。","example":"bank 在河岸与银行语境中含义不同。"},{"week":"W8","category":"图像","term":"Vector graphics","chinese":"矢量图形","concept":"用点、线、曲线和形状的数学描述表示图像。","purpose":"可无损缩放并保留对象结构。","relation":"与像素网格 raster image 对比。","example":"SVG 徽标放大后仍清晰。"},{"week":"W8","category":"图像","term":"Raster image","chinese":"栅格图像","concept":"由固定行列像素矩阵组成的图像。","purpose":"适合照片和逐像素处理。","relation":"分辨率固定，放大会显像素。","example":"JPEG 照片。"},{"week":"W8","category":"图像","term":"Pixel","chinese":"像素","concept":"栅格图像中最小的采样元素。","purpose":"保存某位置的亮度或颜色值。","relation":"多个 channel 共同描述一个彩色像素。","example":"RGB 像素 (255,0,0) 为红色。"},{"week":"W8","category":"图像","term":"Channel","chinese":"通道","concept":"图像中一种颜色或测量维度的二维矩阵。","purpose":"分别保存红、绿、蓝或其他信号。","relation":"RGB 有 3 个通道；灰度通常 1 个。","example":"green channel 可突出某类血管信号。"},{"week":"W8","category":"图像","term":"Bit depth / bpp","chinese":"位深／每像素位数","concept":"用于表示像素或通道的比特数量。","purpose":"决定可表示的强度或颜色级数。","relation":"位深越高级数越多，同时存储量通常更大。","example":"8 bit 可表示 2^8=256 个值。"},{"week":"W8","category":"图像","term":"RGB / TrueColor","chinese":"RGB 真彩色","concept":"用红、绿、蓝三个通道组合颜色的图像。","purpose":"表达常见彩色照片。","relation":"典型真彩色为每通道 8 bit，总计 24 bpp。","example":"(255,255,0) 组合为黄色。"},{"week":"W8","category":"图像","term":"Grayscale image","chinese":"灰度图","concept":"每个像素只保存一个明暗值的单通道图像。","purpose":"降低计算量并突出强度结构。","relation":"不是 binary image；可有许多灰度级。","example":"8-bit 灰度 CT 切片。"},{"week":"W8","category":"图像","term":"Binary image / Mask","chinese":"二值图／掩膜","concept":"像素只有 0/1 或黑/白两类。","purpose":"标记目标区域、前景或有效位置。","relation":"常由 thresholding 或 segmentation 产生。","example":"血管区域为 1，背景为 0。"},{"week":"W8","category":"图像","term":"Image feature","chinese":"图像特征","concept":"从图像提取的可比较数值描述。","purpose":"把视觉内容转换为分类、检索或分析可用的向量。","relation":"可由手工 descriptor 或神经网络学习。","example":"边缘方向直方图。"},{"week":"W8","category":"图像","term":"Classical computer vision","chinese":"传统计算机视觉","concept":"使用人工设计的滤波器、边缘、关键点等算法分析图像。","purpose":"提供可解释的 white-box 特征。","relation":"与深度视觉自动学习 representation 对比。","example":"用 Sobel 算子提取边缘。"},{"week":"W8","category":"图像","term":"Deep computer vision","chinese":"深度计算机视觉","concept":"用深度神经网络从数据学习图像表示。","purpose":"减少手工特征设计并处理复杂语义。","relation":"常见模型包括 CNN 和 Vision Transformer。","example":"模型学习“猫”的 embedding。"},{"week":"W8","category":"图像","term":"CNN (Convolutional Neural Network)","chinese":"卷积神经网络","concept":"利用局部卷积核逐层学习空间模式的网络。","purpose":"从边缘到形状再到对象构建层次特征。","relation":"是深度图像特征提取方法。","example":"用预训练 CNN 为商品图片生成向量。"},{"week":"W8","category":"图像","term":"Vision Transformer (ViT)","chinese":"视觉 Transformer","concept":"把图像切成 patch 并用 Transformer 建模其关系。","purpose":"学习全局图像表示。","relation":"与 CNN 的局部卷积归纳偏置不同。","example":"将 16×16 patch 序列输入 ViT。"},{"week":"W8","category":"图像","term":"Multimodal foundation model","chinese":"多模态基础模型","concept":"同时处理文本、图像等多种模态的大规模预训练模型。","purpose":"连接文字描述和视觉内容。","relation":"可用共享 embedding 支持图文检索。","example":"用文字“红色汽车”搜索图片。"},{"week":"W8","category":"机器学习","term":"Feature extraction","chinese":"特征提取","concept":"把原始文本或图像转换为数值特征。","purpose":"让 ML 算法能够接收非结构化数据。","relation":"位于 preprocessing 后、model training 前。","example":"把邮件转换为 TF-IDF 向量。"},{"week":"W8","category":"机器学习","term":"Embedding","chinese":"嵌入向量","concept":"在连续向量空间中表示词、文档、图像或实体。","purpose":"让语义相近对象在空间中距离更近。","relation":"dense embedding 与 sparse TF-IDF 不同。","example":"两个同义句的向量 cosine 较高。"},{"week":"W8","category":"机器学习","term":"Derived data product","chinese":"派生数据产品","concept":"由原始数据计算出的可复用结果，如特征或 embedding。","purpose":"需要版本、质量、血缘和存储管理。","relation":"不是临时中间值；它也属于数据工程资产。","example":"保存图片 embedding 供搜索服务使用。"},{"week":"W8","category":"机器学习","term":"Supervised learning","chinese":"监督学习","concept":"使用带正确答案 label 的训练数据学习映射。","purpose":"做分类或回归预测。","relation":"与无标签的 unsupervised learning 对比。","example":"用标注 spam/not-spam 邮件训练分类器。"},{"week":"W8","category":"机器学习","term":"Ground truth / Label","chinese":"真实标签／标注","concept":"训练或评估时作为正确答案的目标值。","purpose":"指导监督模型并衡量预测误差。","relation":"标签质量直接限制模型质量。","example":"邮件人工标为 spam=1。"},{"week":"W8","category":"机器学习","term":"Classification","chinese":"分类","concept":"预测离散类别的监督学习任务。","purpose":"决定对象属于哪个类别。","relation":"离散输出；regression 输出连续数值。","example":"预测图片是猫还是狗。"},{"week":"W8","category":"机器学习","term":"Regression","chinese":"回归","concept":"预测连续数值的监督学习任务。","purpose":"估计价格、温度等数量。","relation":"不要因使用“回归模型”就把离散标签当连续目标。","example":"预测房价 850000。"},{"week":"W8","category":"机器学习","term":"Unsupervised learning","chinese":"无监督学习","concept":"在没有 label 的数据中寻找结构或分布。","purpose":"用于聚类、降维和异常发现。","relation":"不能直接用“准确率”对照未知标签。","example":"按 embedding 将新闻自动分组。"},{"week":"W8","category":"机器学习","term":"Clustering","chinese":"聚类","concept":"按相似性把未标注对象分成组。","purpose":"发现潜在群体结构。","relation":"是无监督学习典型任务。","example":"把客户按购买行为分群。"},{"week":"W8","category":"机器学习","term":"Train/test split","chinese":"训练／测试集划分","concept":"将数据分为拟合模型和最终评估的互斥集合。","purpose":"估计模型对未见数据的泛化能力。","relation":"预处理器也必须只在训练集 fit。","example":"80% 训练、20% 测试。"},{"week":"W8","category":"机器学习","term":"Data leakage","chinese":"数据泄漏","concept":"训练过程使用了预测时不可获得或测试集的信息。","purpose":"识别并防止虚高评估。","relation":"时间序列尤其不能使用未来值。","example":"在划分前用全体数据均值标准化。"},{"week":"W8","category":"文本特征","term":"Tokenisation","chinese":"分词／标记化","concept":"把文本拆成 token 单元。","purpose":"建立词表、计数或送入语言模型。","relation":"token 不一定等于完整单词。","example":"“data-driven”可被拆成多个 token。"},{"week":"W8","category":"文本特征","term":"Normalisation","chinese":"文本规范化","concept":"统一大小写、字符形式等表面差异。","purpose":"减少相同内容产生多个特征。","relation":"过度规范化可能删除任务信号。","example":"将 Data 和 data 都转为 data。"},{"week":"W8","category":"文本特征","term":"Stemming","chinese":"词干提取","concept":"用规则截断词尾得到近似词干。","purpose":"合并词形并缩小词表。","relation":"可能产生非真实单词；lemmatisation 更语言学化。","example":"connected、connecting → connect。"},{"week":"W8","category":"文本特征","term":"Lemmatisation","chinese":"词形还原","concept":"依据词性和词典把词变为规范词元。","purpose":"更准确地合并变形。","relation":"通常比 stemming 计算更复杂。","example":"was → be。"},{"week":"W8","category":"文本特征","term":"Stop words","chinese":"停用词","concept":"频繁出现且常被认为信息量低的词。","purpose":"可减少维度和噪声。","relation":"不能机械删除；not 对情感非常重要。","example":"the、a 常是停用词。"},{"week":"W8","category":"文本特征","term":"Bag of Words (BoW)","chinese":"词袋模型","concept":"忽略词序，只记录词出现情况或次数。","purpose":"把文档转换为固定长度稀疏向量。","relation":"简单可解释，但丢失语序和上下文。","example":"“dog bites man”与“man bites dog”词袋相同。"},{"week":"W8","category":"文本特征","term":"Term Frequency (TF)","chinese":"词频","concept":"词在一个文档中的出现次数或规范化频率。","purpose":"衡量词对该文档的局部重要性。","relation":"TF-IDF 还会乘 inverse document frequency。","example":"某词在文档出现 4 次，TF 可为 4。"},{"week":"W8","category":"文本特征","term":"IDF (Inverse Document Frequency)","chinese":"逆文档频率","concept":"根据词出现在多少文档中降低常见词权重。","purpose":"突出能区分少数文档的词。","relation":"df 越大，IDF 越小。","example":"只在少量文档出现的 database 权重较高。"},{"week":"W8","category":"文本特征","term":"TF-IDF","chinese":"词频—逆文档频率","concept":"用 TF×IDF 衡量词对某文档的区分性。","purpose":"构建可用于分类和检索的稀疏表示。","relation":"高值表示在该文档常见但全语料不普遍。","example":"tfidf(t,d)=tf(t,d)×log(N/df(t))。"},{"week":"W8","category":"文本特征","term":"Sparse vector / Sparse matrix","chinese":"稀疏向量／矩阵","concept":"绝大多数元素为 0 的表示。","purpose":"节省高维词表特征的存储与计算。","relation":"BoW/TF-IDF 常稀疏；neural embedding 通常 dense。","example":"10 万词词表中一封邮件只出现 80 个词。"},{"week":"W8","category":"文本特征","term":"Vector Space Model","chinese":"向量空间模型","concept":"用特征向量表示文档，并以几何关系比较。","purpose":"把文本搜索转为距离或相似度计算。","relation":"与 cosine similarity 配合常见。","example":"查询向量与文档向量比较夹角。"},{"week":"W8","category":"文本特征","term":"Cosine similarity","chinese":"余弦相似度","concept":"向量点积除以长度乘积，衡量方向相似度。","purpose":"比较长度不同的文本向量。","relation":"值越大越相似；cosine distance 方向相反。","example":"[1,1] 与 [2,2] 的 cosine 为 1。"},{"week":"W8","category":"文本特征","term":"CountVectorizer","chinese":"计数向量器","concept":"scikit-learn 中学习词表并输出 token 计数矩阵的工具。","purpose":"自动完成常用 tokenisation 和 BoW 转换。","relation":"必须在训练集 fit，再对测试集 transform。","example":"CountVectorizer(ngram_range=(1,2))。"},{"week":"W8","category":"文本特征","term":"N-gram / Bigram","chinese":"N 元语法／二元词组","concept":"由连续 N 个 token 组成的特征。","purpose":"保留有限局部词序。","relation":"维度比 unigram 更高。","example":"bigram “New York”。"},{"week":"W8","category":"语言模型","term":"Word2Vec","chinese":"词向量模型","concept":"根据词的上下文学习相对固定的 dense word embedding。","purpose":"捕捉词语相似关系。","relation":"通常每个词一个向量；BERT 根据句子上下文改变表示。","example":"king 与 queen 向量接近。"},{"week":"W8","category":"语言模型","term":"GloVe","chinese":"全局词向量模型","concept":"利用语料全局词共现统计学习静态词向量。","purpose":"生成可复用 dense embedding。","relation":"与 Word2Vec 都偏静态；训练思想不同。","example":"用预训练 GloVe 初始化文本模型。"},{"week":"W8","category":"语言模型","term":"BERT","chinese":"双向编码器 Transformer","concept":"利用左右文共同生成上下文化表示的 encoder-only 预训练模型。","purpose":"适合文本理解、分类、NER，可 fine-tune。","relation":"与自回归生成型 GPT 侧重点不同。","example":"bank 在不同句子中得到不同向量。"},{"week":"W8","category":"语言模型","term":"GPT","chinese":"生成式预训练 Transformer","concept":"按前文预测下一个 token 的自回归 decoder 型模型。","purpose":"擅长生成和续写，也可完成多种语言任务。","relation":"BERT 双向编码理解；GPT 因果方向生成。","example":"给定问题逐 token 生成回答。"},{"week":"W8","category":"语言模型","term":"Fine-tuning","chinese":"微调","concept":"在预训练模型上用特定任务数据继续训练。","purpose":"让通用表示适应分类、NER 等目标。","relation":"不同于从零训练。","example":"用标注邮件微调 BERT 做 spam 分类。"},{"week":"W8","category":"文本任务","term":"Named Entity Recognition (NER)","chinese":"命名实体识别","concept":"识别人名、组织、地点等实体及类别。","purpose":"把非结构化文本转为结构化实体字段。","relation":"属于 NLP 信息抽取。","example":"从新闻中提取 “University of Sydney”。"},{"week":"W8","category":"图像特征","term":"ROI (Region of Interest)","chinese":"感兴趣区域","concept":"图像中需要重点分析的区域。","purpose":"减少无关背景并产生局部测量。","relation":"可由人工框选、segmentation 或 detector 得到。","example":"只分析医学图像中的血管区域。"},{"week":"W8","category":"图像特征","term":"Image descriptor","chinese":"图像描述子","concept":"人工算法生成的局部或全局特征向量。","purpose":"支持可解释的匹配与检索。","relation":"属于 white-box feature extraction。","example":"SIFT 风格关键点描述子。"},{"week":"W8","category":"图像特征","term":"Image gradient","chinese":"图像梯度","concept":"像素强度或颜色在空间中的变化率。","purpose":"检测边缘、方向和纹理。","relation":"许多传统 descriptor 以梯度为基础。","example":"物体边界处梯度较大。"},{"week":"W8","category":"图像特征","term":"Edge / Keypoint / Segmentation","chinese":"边缘／关键点／分割","concept":"边缘标变化；关键点标稳定局部位置；分割给像素分区域。","purpose":"分别支持轮廓、匹配和区域级分析。","relation":"三者粒度和输出不同。","example":"分割输出每个像素的类别 mask。"},{"week":"W8","category":"图像特征","term":"White-box vs Black-box","chinese":"白盒与黑盒方法","concept":"白盒规则明确可解释；黑盒模型从数据学习复杂表示。","purpose":"帮助选择可解释性与表现的取舍。","relation":"手工 gradient descriptor 是白盒，CNN embedding 常视为黑盒。","example":"监管场景可能偏好可解释特征。"},{"week":"W8","category":"图像特征","term":"Image similarity search","chinese":"相似图片搜索","concept":"把查询图和库中图片变成同类向量并搜索近邻。","purpose":"按视觉内容而非文件名检索。","relation":"核心是相同 feature extractor、distance 和 index。","example":"上传鞋子照片找到外观相似商品。"},{"week":"W8","category":"图像处理","term":"Noise reduction","chinese":"降噪","concept":"减少随机像素变化。","purpose":"让边缘、分割和测量更稳定。","relation":"属于 preprocessing，不等于特征提取。","example":"Gaussian blur 降低传感噪声。"},{"week":"W8","category":"图像处理","term":"Morphological operations","chinese":"形态学操作","concept":"按结构元素对二值或灰度形状膨胀、腐蚀等。","purpose":"去除小噪点、填洞和连接区域。","relation":"常作用于 mask。","example":"opening 去除孤立白点。"},{"week":"W8","category":"图像处理","term":"Thresholding","chinese":"阈值化","concept":"按像素值阈值把图像分成类别。","purpose":"快速生成 binary mask。","relation":"全局阈值可能受光照变化影响。","example":"强度 >128 设为前景 1。"},{"week":"W8","category":"元数据","term":"Metadata","chinese":"元数据","concept":"描述数据对象来源、时间、位置、设备、作者等的信息。","purpose":"用于检索、连接、验证和特征工程。","relation":"它可能缺失、被修改或与内容不一致。","example":"照片的拍摄时间与 GPS。"},{"week":"W8","category":"元数据","term":"EXIF","chinese":"可交换图像文件元数据标准","concept":"常保存相机、曝光、拍摄时间和 GPS 等标签。","purpose":"自动获取数字照片技术信息。","relation":"是 metadata 体系之一，不保证所有字段存在。","example":"读取 CreateDate。"},{"week":"W8","category":"元数据","term":"IPTC","chinese":"新闻与媒体元数据标准","concept":"保存标题、作者、版权和关键词等编辑信息。","purpose":"支持媒体资产管理。","relation":"与 EXIF 的设备技术信息侧重点不同。","example":"新闻图片含 caption 与 copyright。"},{"week":"W8","category":"元数据","term":"XMP","chinese":"可扩展元数据平台","concept":"Adobe 发起的可扩展键值元数据格式。","purpose":"跨文件类型嵌入或伴随描述信息。","relation":"可与 EXIF/IPTC 同时存在。","example":"PDF 中保存作者和编辑工具。"},{"week":"W8","category":"元数据","term":"ExifTool","chinese":"元数据命令行工具","concept":"读取、写入并批量导出多种文件元数据。","purpose":"把 EXIF/IPTC/XMP 自动转为 CSV/JSON 管线输入。","relation":"工具输出仍需验证时间、GPS和缺失值。","example":"exiftool -common -csv *.jpg > metadata.csv。"},{"week":"W8","category":"特征工程","term":"Feature engineering","chinese":"特征工程","concept":"把原始数据转换为更能表达预测问题的特征。","purpose":"提高模型效果、稳定性和可解释性。","relation":"包括交互、时间、编码、选择等方法。","example":"由 height、weight 计算 BMI。"},{"week":"W8","category":"特征工程","term":"Feature interaction","chinese":"特征交互","concept":"组合两个或多个特征表达联合效应。","purpose":"捕捉单个变量无法表示的关系。","relation":"可用 product、ratio 等。","example":"房屋面积÷卧室数。"},{"week":"W8","category":"特征工程","term":"Polynomial feature","chinese":"多项式特征","concept":"加入平方、立方或变量乘积等高阶项。","purpose":"让简单模型拟合非线性关系。","relation":"可能迅速增加维度并过拟合。","example":"x²、x1×x2。"},{"week":"W8","category":"特征工程","term":"Lag feature","chinese":"滞后特征","concept":"使用前一个或更早时间点的值作为当前特征。","purpose":"让模型利用历史依赖进行预测。","relation":"只能使用预测时已知的过去值。","example":"用昨天销量预测今天销量。"},{"week":"W8","category":"特征工程","term":"Rolling / Aggregated feature","chinese":"滚动／聚合特征","concept":"在过去固定窗口上计算均值、总和等。","purpose":"平滑噪声并表达近期趋势。","relation":"窗口必须只看过去以防 leakage。","example":"过去 7 天平均温度。"},{"week":"W8","category":"特征工程","term":"One-hot encoding","chinese":"独热编码","concept":"把每个类别变成一个 0/1 列。","purpose":"让模型使用无自然顺序的类别。","relation":"高基数类别会产生高维稀疏矩阵。","example":"颜色 red/blue → 两个二进制列。"},{"week":"W8","category":"特征工程","term":"Target encoding","chinese":"目标编码","concept":"用某类别对应目标值的统计量替代类别。","purpose":"压缩高基数类别。","relation":"必须用训练折或平滑，避免标签泄漏。","example":"用邮编对应训练集平均房价编码邮编。"},{"week":"W8","category":"特征工程","term":"Feature hashing","chinese":"特征哈希","concept":"用哈希把类别映射到固定数量桶。","purpose":"控制维度并处理新类别。","relation":"可能发生 collision。","example":"百万 URL 映射到 2^18 个槽。"},{"week":"W8","category":"特征工程","term":"Feature selection","chinese":"特征选择","concept":"保留有用特征并删除冗余或噪声特征。","purpose":"降低维度、成本和过拟合风险。","relation":"分 filter、wrapper、embedded。","example":"选择与目标相关的 30 个变量。"},{"week":"W8","category":"特征工程","term":"Filter / Wrapper / Embedded methods","chinese":"过滤／包装／嵌入式选择","concept":"分别按统计分数、模型性能搜索、训练过程内置机制选特征。","purpose":"提供不同计算成本与模型依赖的选择策略。","relation":"RFE 是 wrapper；LASSO 可作 embedded。","example":"先用相关系数 filter 删除弱特征。"},{"week":"W8","category":"特征工程","term":"AutoML / FeatureTools","chinese":"自动机器学习／自动特征工具","concept":"自动尝试模型、参数或从关系数据生成候选特征的工具。","purpose":"减少重复探索并扩大候选空间。","relation":"自动化结果仍需防 leakage 和验证业务含义。","example":"FeatureTools 生成客户历史交易聚合。"},{"week":"W9","category":"基础","term":"Data stream","chinese":"数据流","concept":"持续到达、随时间变化且潜在无界的 tuple／event 序列。","purpose":"表示实时交易、日志和传感数据。","relation":"与有界 batch dataset 对比。","example":"银行卡交易不断进入反欺诈系统。"},{"week":"W9","category":"基础","term":"Unbounded stream","chinese":"无界流","concept":"没有预先已知终点的数据序列。","purpose":"说明不能等全部数据到齐才计算。","relation":"window 把无界流暂时切成有限 relation。","example":"运行中的温度传感器流。"},{"week":"W9","category":"基础","term":"Event / Record / Message / Tuple","chinese":"事件／记录／消息／元组","concept":"流中的单个原子数据项。","purpose":"是发布、传输和算子处理的基本单位。","relation":"不同平台用词不同，通常都含 payload 和 metadata。","example":"{device:'A',temp:21,ts:'12:00'}。"},{"week":"W9","category":"基础","term":"Data in motion","chinese":"运动中的数据","concept":"数据到达时就被处理，而不是先完整存储。","purpose":"实现低延迟实时响应。","relation":"与传统 DBMS 的 data at rest 对比。","example":"交易到达即评分并决定是否拦截。"},{"week":"W9","category":"基础","term":"Real-time / Near-real-time","chinese":"实时／近实时","concept":"在业务允许的很短延迟内产生结果。","purpose":"支持告警、推荐和欺诈检测。","relation":"实时不必等于零延迟；要看 latency SLA。","example":"异常交易在数百毫秒内告警。"},{"week":"W9","category":"系统","term":"DBMS","chinese":"数据库管理系统","concept":"对持久 relation 执行临时查询和更新。","purpose":"管理 data at rest 与精确查询结果。","relation":"DSMS 则让 continuous query 长期处理 transient stream。","example":"用户提交一次 SELECT 后得到结果。"},{"week":"W9","category":"系统","term":"DSMS (Data Stream Management System)","chinese":"数据流管理系统","concept":"注册持续查询并对不断到来的流增量计算。","purpose":"处理无界、乱序、高速事件。","relation":"把传统 query-over-data 转成 data-through-query。","example":"持续计算最近 5 分钟平均温度。"},{"week":"W9","category":"查询","term":"Continuous query","chinese":"连续查询","concept":"长期运行、随新事件到达不断更新结果的查询。","purpose":"避免反复手工执行批查询。","relation":"是 DSMS 的核心查询模式。","example":"注册“每分钟统计支付失败数”。"},{"week":"W9","category":"架构","term":"Stream processing architecture","chinese":"流处理架构","concept":"把消息摄取层与查询计算层组合的系统设计。","purpose":"同时解决可靠接收和有明确语义的计算。","relation":"Kafka/MQTT 常负责消息；Spark/Flink 负责处理。","example":"producer→Kafka→Flink→sink。"},{"week":"W9","category":"消息","term":"Publish/Subscribe (Pub/Sub)","chinese":"发布／订阅","concept":"publisher 按 topic 发布，subscriber 按 topic 接收，由 broker 解耦双方。","purpose":"让多个生产者与消费者异步扩展。","relation":"不自动等同于 exactly-once 业务语义。","example":"传感器发 temp topic，仪表盘和告警同时订阅。"},{"week":"W9","category":"消息","term":"Publisher / Producer","chinese":"发布者／生产者","concept":"生成并发送消息的组件。","purpose":"把源事件写入 topic 或 broker。","relation":"producer 不需要知道具体 consumer。","example":"mqtt_publisher.py 发送天气记录。"},{"week":"W9","category":"消息","term":"Subscriber / Consumer","chinese":"订阅者／消费者","concept":"接收并处理 topic 中消息的组件。","purpose":"执行解析、计算或写入下游。","relation":"多个 consumer 可独立订阅或组成 consumer group。","example":"告警服务读取温度消息。"},{"week":"W9","category":"消息","term":"Broker","chinese":"消息代理","concept":"接收、路由并按系统能力保存消息的中间服务。","purpose":"解耦 producer 与 consumer。","relation":"MQTT broker 和 Kafka broker 的存储模型不同。","example":"Mosquitto 接收 MQTT publish 并分发。"},{"week":"W9","category":"消息","term":"Topic / Feed","chinese":"主题／消息流名称","concept":"用于分类和路由消息的逻辑通道。","purpose":"让订阅者只接收关心的数据。","relation":"MQTT topic 是层级字符串；Kafka topic 分为 partitions。","example":"building/3/temperature。"},{"week":"W9","category":"MQTT","term":"MQTT","chinese":"消息队列遥测传输协议","concept":"面向 IoT 的轻量级 Pub/Sub 协议。","purpose":"在网络和设备资源有限时传输传感消息。","relation":"它是 messaging protocol，不是复杂 stream processor。","example":"Paho client 向 Mosquitto broker 发布 JSON。"},{"week":"W9","category":"MQTT","term":"Mosquitto","chinese":"Mosquitto MQTT 代理","concept":"Eclipse 提供的开源 MQTT broker。","purpose":"在本地或服务器上接收和分发 MQTT 消息。","relation":"与 Paho client library 配合。","example":"mosquitto 在 1883 端口监听。"},{"week":"W9","category":"MQTT","term":"Paho MQTT","chinese":"Paho MQTT 客户端库","concept":"为 Python 等语言提供 MQTT publish/subscribe API。","purpose":"编写 publisher、subscriber 和 callback。","relation":"Paho 是 client，不是 broker。","example":"client.subscribe('sensor/#')。"},{"week":"W9","category":"MQTT","term":"Callback","chinese":"回调函数","concept":"特定事件发生时由框架自动调用的函数。","purpose":"异步处理收到的消息或连接事件。","relation":"不是普通顺序主动调用。","example":"on_message 中 decode payload 再 json.loads。"},{"week":"W9","category":"MQTT","term":"Payload","chinese":"消息负载","concept":"消息实际携带的数据字节。","purpose":"承载 JSON、文本或二进制事件内容。","relation":"topic 用于路由，payload 用于业务数据。","example":"message.payload.decode('utf-8')。"},{"week":"W9","category":"MQTT","term":"Single-level wildcard +","chinese":"单层通配符","concept":"MQTT 订阅过滤器中匹配恰好一层 topic。","purpose":"一次订阅多个同层设备或楼层。","relation":"+ 不跨越 /；# 匹配后续多层。","example":"home/+/temp 匹配 home/kitchen/temp。"},{"week":"W9","category":"MQTT","term":"Multi-level wildcard #","chinese":"多层通配符","concept":"匹配当前位置之后的所有 topic 层级，通常必须位于末尾。","purpose":"订阅一个分支下全部消息。","relation":"范围比 + 更广。","example":"home/# 匹配 home/kitchen/temp 与 home/door。"},{"week":"W9","category":"MQTT","term":"Retained message","chinese":"保留消息","concept":"broker 为 topic 保存最后一条 retain 消息并立即发给新订阅者。","purpose":"让新订阅者获得最新状态。","relation":"retain 与 QoS 是两个独立设置。","example":"新仪表盘连接后立即得到最后温度。"},{"week":"W9","category":"MQTT","term":"QoS 0 — At most once","chinese":"服务质量0／至多一次","concept":"消息最多交付一次，可能丢失且不重试。","purpose":"提供最低开销和最低延迟。","relation":"适合允许少量丢失的高频遥测。","example":"每秒温度采样偶尔丢一条可接受。"},{"week":"W9","category":"MQTT","term":"QoS 1 — At least once","chinese":"服务质量1／至少一次","concept":"通过确认和重传避免丢失，但可能重复。","purpose":"适合不能漏消息且 consumer 可去重的场景。","relation":"需要 idempotent consumer。","example":"订单事件带 event_id 去重。"},{"week":"W9","category":"MQTT","term":"QoS 2 — Exactly once delivery","chinese":"服务质量2／协议层恰好一次交付","concept":"用更多握手避免协议层重复交付。","purpose":"在高价值且低吞吐场景提高交付保证。","relation":"不单独保证数据库副作用端到端 exactly-once。","example":"支付指令协议传输使用 QoS2。"},{"week":"W9","category":"可靠性","term":"Idempotence","chinese":"幂等性","concept":"相同操作执行多次与执行一次结果相同。","purpose":"安全处理重试和重复消息。","relation":"是 QoS1/at-least-once 管道的关键设计。","example":"按唯一 event_id UPSERT 而非重复 INSERT。"},{"week":"W9","category":"可靠性","term":"Acknowledgement (ACK)","chinese":"确认消息","concept":"接收方通知发送方消息已收到或处理到某阶段。","purpose":"决定是否重传。","relation":"ACK 过早可能在业务写入前崩溃而丢结果。","example":"consumer 成功写库后提交 offset。"},{"week":"W9","category":"Kafka","term":"Apache Kafka","chinese":"分布式持久化 Pub/Sub 日志平台","concept":"高吞吐地保存、复制和重放事件流。","purpose":"连接多源、多消费者与 stream processor。","relation":"比轻量 MQTT 更强调 durable partitioned log。","example":"Web 日志写 Kafka 后由 Spark 与 Flink 分别消费。"},{"week":"W9","category":"Kafka","term":"Partitioned log","chinese":"分区日志","concept":"topic 被拆成多个仅追加、有序的 partition。","purpose":"通过分区实现并行、扩展和持久重放。","relation":"只保证 partition 内顺序，不保证跨 partition 全局顺序。","example":"相同 account_id 作为 key 进入同一 partition。"},{"week":"W9","category":"Kafka","term":"Partition","chinese":"分区","concept":"Kafka topic 的并行和顺序单位。","purpose":"分散存储与 consumer 工作。","relation":"consumer group 内一个 partition 同时分配给一个 consumer。","example":"6 partitions 最多让组内 6 个 consumer 同时有活。"},{"week":"W9","category":"Kafka","term":"Offset","chinese":"偏移量","concept":"record 在 Kafka partition 内的位置编号。","purpose":"追踪消费进度并支持 replay。","relation":"offset 只在所属 partition 内有意义。","example":"consumer 从 offset 120 重新读取。"},{"week":"W9","category":"Kafka","term":"Consumer group","chinese":"消费者组","concept":"多个 consumer 协作分摊同一 topic partitions 的逻辑组。","purpose":"扩展同一应用的并行消费。","relation":"不同 group 各自收到完整流；同组实例分工。","example":"analytics 组与 archive 组各读取所有消息。"},{"week":"W9","category":"Kafka","term":"Replication factor","chinese":"复制因子","concept":"每个 Kafka partition 保留的副本数量。","purpose":"容忍 broker 故障并提高可用性。","relation":"N 个副本理论上可容忍至多 N−1 个副本节点故障，仍取决于 leader/ISR。","example":"replication factor=3。"},{"week":"W9","category":"Kafka","term":"Replay","chinese":"重放","concept":"从旧 offset 再次读取历史消息。","purpose":"恢复、重算或建立新下游。","relation":"依赖 Kafka retention 仍保留数据。","example":"修复 bug 后从昨天 offset 重算。"},{"week":"W9","category":"算子","term":"Stateless operator","chinese":"无状态算子","concept":"每个输出只依赖当前输入事件。","purpose":"易扩展、恢复和并行。","relation":"selection、逐条 projection 常是 stateless。","example":"过滤 length>512。"},{"week":"W9","category":"算子","term":"Stateful operator","chinese":"有状态算子","concept":"输出依赖多个事件或过去信息。","purpose":"支持聚合、去重、窗口和 join。","relation":"需要状态存储、checkpoint 和清理。","example":"计算每个设备最近 10 分钟平均值。"},{"week":"W9","category":"算子","term":"Selection / Projection","chinese":"选择／投影","concept":"selection 按条件筛行；projection 选择或计算字段。","purpose":"执行逐事件过滤和映射。","relation":"在不去重时可逐条无状态处理。","example":"WHERE length>512；SELECT sourceIP,time。"},{"week":"W9","category":"窗口","term":"Window","chinese":"窗口","concept":"从无限流抽取有限 relation 的规则。","purpose":"为聚合、join 和排序提供有限范围。","relation":"可按时间、tuple count、punctuation 或 session 定义。","example":"最近 5 分钟交易。"},{"week":"W9","category":"窗口","term":"Tumbling window","chinese":"滚动不重叠窗口","concept":"固定长度且首尾相接、不重叠的窗口。","purpose":"每个事件通常只进入一个窗口。","relation":"与 sliding window 可重叠不同。","example":"每个整点划分 1 小时统计。"},{"week":"W9","category":"窗口","term":"Sliding window","chinese":"滑动窗口","concept":"具有 window size 和 slide/step，窗口可重叠。","purpose":"提供连续更新的近期统计。","relation":"当 size>slide 时，一个事件可属于多个窗口。","example":"10 分钟窗口每 5 分钟滑动。"},{"week":"W9","category":"窗口","term":"Fixed window","chinese":"固定窗口","concept":"按预定固定时间边界划分的窗口。","purpose":"周期性汇总。","relation":"常对应 tumbling window。","example":"每 1 分钟一个窗口。"},{"week":"W9","category":"窗口","term":"Tuple-count window","chinese":"计数窗口","concept":"按最近 N 条 tuple 而非时间长度取窗口。","purpose":"处理速率相关的最近事件集合。","relation":"相同 timestamp 的 tie 可能导致非确定边界。","example":"最近 100 笔交易。"},{"week":"W9","category":"窗口","term":"Punctuation-based window","chinese":"标点窗口","concept":"由流中显式边界 marker 开始或结束窗口。","purpose":"处理数据自身定义的可变批次。","relation":"既不必是 sliding，也不必是固定 tumbling。","example":"auction_end 标记结束一场拍卖。"},{"week":"W9","category":"窗口","term":"Session window","chinese":"会话窗口","concept":"按同一实体连续活动及 inactivity gap 分组。","purpose":"捕捉长度可变的用户或设备会话。","relation":"边界由活动间隔而非固定时钟决定。","example":"用户 30 分钟无操作则结束 session。"},{"week":"W9","category":"时间语义","term":"Event time","chinese":"事件时间","concept":"事件在源端真实发生的时间。","purpose":"在乱序到达时仍按业务时间计算正确窗口。","relation":"需要 timestamp、watermark 和 late-event 策略。","example":"传感器 12:00 测量、12:05 才上传。"},{"week":"W9","category":"时间语义","term":"Ingestion time","chinese":"摄取时间","concept":"事件进入流处理系统的时间。","purpose":"在源时间缺失时提供较稳定的入口时间。","relation":"包含网络传输延迟，不等于真实发生时间。","example":"Kafka source 12:05 收到事件。"},{"week":"W9","category":"时间语义","term":"Processing time","chinese":"处理时间","concept":"算子实际处理事件时机器的墙钟时间。","purpose":"实现简单、延迟低。","relation":"结果受负载和重试影响，业务时间正确性较弱。","example":"Flink operator 12:05:02 执行。"},{"week":"W9","category":"时间语义","term":"Out-of-order event","chinese":"乱序事件","concept":"事件到达顺序与 event time 顺序不同。","purpose":"解释为什么需要 event time 与 watermark。","relation":"网络、重试和多分区都会造成乱序。","example":"12:02 事件先于 12:01 事件到达。"},{"week":"W9","category":"时间语义","term":"Late event / Allowed lateness","chinese":"迟到事件／允许迟到量","concept":"watermark 越过相关窗口后才到达的事件，以及系统仍接受它的时限。","purpose":"控制正确性、等待时间和状态成本。","relation":"非常晚的数据可丢弃、更新结果或送 side output。","example":"允许迟到 2 分钟后仍更新窗口。"},{"week":"W9","category":"时间语义","term":"Watermark","chinese":"水位线","concept":"系统对 event time 已推进到何处的估计。","purpose":"触发窗口关闭、输出和状态清理。","relation":"不是此前绝无新事件的绝对保证。","example":"watermark=12:10 表示系统认为大部分更早事件已到。"},{"week":"W9","category":"时间语义","term":"WatermarkStrategy","chinese":"水位线策略","concept":"Flink 中从时间戳和迟到假设生成 watermark 的配置。","purpose":"统一 timestamp 提取、周期水位线和最大乱序量。","relation":"策略过激会把正常事件判为 late。","example":"forBoundedOutOfOrderness(Duration.ofSeconds(5))。"},{"week":"W9","category":"连接","term":"Stream-table join / Enrichment","chinese":"流—表连接／增强","concept":"每个流事件查静态或较慢更新的参考表。","purpose":"补充类别、客户、设备等上下文。","relation":"通常比 stream-stream join 状态更可控。","example":"交易流 join 商户风险等级表。"},{"week":"W9","category":"连接","term":"Stream-stream join","chinese":"流—流连接","concept":"在 key 和有限时间范围内匹配两个无界流。","purpose":"关联同时发生的实时事件。","relation":"必须限制时间，否则状态可能无限增长。","example":"点击后 30 分钟内匹配购买。"},{"week":"W9","category":"连接","term":"Join key","chinese":"连接键","concept":"决定两侧记录是否属于同一实体的字段。","purpose":"缩小 join 候选并分区状态。","relation":"相同 key 仍需时间条件控制窗口。","example":"user_id。"},{"week":"W9","category":"连接","term":"Redis lookup","chinese":"Redis 快速查找","concept":"使用内存键值库为事件提供参考数据。","purpose":"降低 stream-table enrichment 延迟。","relation":"缓存可能陈旧，需要刷新策略。","example":"按 product_id 查产品类别。"},{"week":"W9","category":"Spark","term":"Spark Streaming","chinese":"Spark 的流处理组件","concept":"把输入流切成 micro-batch，并用 Spark 引擎处理。","purpose":"复用 RDD/集群生态做窗口和聚合。","relation":"课程材料强调 micro-batching；与 Flink pipelining 对比。","example":"每秒生成一个 RDD 处理 socket 数据。"},{"week":"W9","category":"Spark","term":"Micro-batch","chinese":"微批","concept":"把短时间内到达的事件组成小批次执行。","purpose":"在批处理引擎上实现流式计算。","relation":"仍属于流处理，但延迟通常受 batch interval 限制。","example":"每 1 秒处理一次该秒所有消息。"},{"week":"W9","category":"Spark","term":"DStream (Discretized Stream)","chinese":"离散流","concept":"Spark Streaming 中由一系列连续 RDD 构成的流抽象。","purpose":"对每个 micro-batch 应用转换。","relation":"DStream 的每个时间片底层是 RDD。","example":"lines.flatMap(...).reduceByKeyAndWindow(...)。"},{"week":"W9","category":"Spark","term":"RDD (Resilient Distributed Dataset)","chinese":"弹性分布式数据集","concept":"可分区、不可变、可由 lineage 重建的分布式集合。","purpose":"提供 Spark 容错和并行计算基础。","relation":"DStream 是 RDD 序列；DataFrame 也最终在 Spark 执行引擎上运行。","example":"一个 RDD 保存某秒到达的词。"},{"week":"W9","category":"Flink","term":"Apache Flink","chinese":"分布式数据流处理框架","concept":"以连续 pipelining、状态和 event-time 支持见长。","purpose":"低延迟处理乱序流、窗口和状态。","relation":"Kafka/MQTT 负责消息，Flink 负责计算。","example":"DataStream.keyBy(...).window(...).sum(...)。"},{"week":"W9","category":"Flink","term":"Pipelining","chinese":"流水线执行","concept":"上游生成记录后立即转给可用下游算子。","purpose":"让不同算子阶段重叠并降低延迟。","relation":"与 Spark 经典 stage/micro-batch 边界对比。","example":"map 输出立即进入 reduce。"},{"week":"W9","category":"可靠性","term":"Checkpoint","chinese":"检查点","concept":"周期性保存算子状态与输入位置的一致快照。","purpose":"失败后恢复 stateful processing。","relation":"端到端 exactly-once 还依赖可重放 source 和事务／幂等 sink。","example":"Flink 从 checkpoint 恢复窗口状态和 Kafka offset。"},{"week":"W9","category":"可靠性","term":"Side output","chinese":"侧输出","concept":"把特定事件从主结果流分流到独立流。","purpose":"保存太晚、异常或解析失败的数据。","relation":"比静默丢弃更便于审计。","example":"late events 进入 late-data topic。"},{"week":"W9","category":"性能","term":"Bursty stream / Backpressure","chinese":"突发流／背压","concept":"输入速率突然升高；下游处理不过来时压力向上游传播。","purpose":"防止无界缓冲并协调速率。","relation":"窗口和 watermark 也会受积压影响。","example":"促销开始后消息速率暴增。"},{"week":"W10","category":"扩展性","term":"Scalability","chinese":"可扩展性","concept":"工作量增长时增加资源仍能维持可接受性能的能力。","purpose":"评估系统能否持续承载更多数据和用户。","relation":"要结合 throughput、latency、成本和效率判断。","example":"数据量十倍后扩容仍能按 SLA 完成。"},{"week":"W10","category":"扩展性","term":"Scale-up (vertical scaling)","chinese":"纵向扩展","concept":"给单机增加 CPU、内存或磁盘。","purpose":"在架构变化较小时提升单机能力。","relation":"受硬件上限和单点故障限制；不要与课程的 scale-up 性能目标混淆。","example":"把服务器从 16 核升级到 64 核。"},{"week":"W10","category":"扩展性","term":"Scale-out (horizontal scaling)","chinese":"横向扩展","concept":"增加更多服务器并把工作分散到集群。","purpose":"突破单机上限并提高容量。","relation":"需要 partitioning、coordination 和 fault tolerance。","example":"从 4 个 worker 扩为 20 个。"},{"week":"W10","category":"扩展性","term":"Speed-up","chinese":"加速比","concept":"固定数据量时，增加资源后运行时间缩短的比例。","purpose":"衡量并行化效果。","relation":"S(p)=T1/Tp；协调和串行部分使其通常低于 p。","example":"100 秒降到 25 秒，speedup=4。"},{"week":"W10","category":"扩展性","term":"Scale-up goal / Size-up","chinese":"同比扩容目标","concept":"数据量和资源同比增加时，运行时间或吞吐表现保持近似不变。","purpose":"衡量系统处理更大问题的能力。","relation":"与固定数据量的 speed-up 不同。","example":"数据×4、节点×4，时间仍约 10 分钟。"},{"week":"W10","category":"性能","term":"Throughput","chinese":"吞吐量","concept":"单位时间内完成的记录、请求或数据量。","purpose":"衡量系统总处理能力。","relation":"高 throughput 不等于单条低 latency。","example":"每秒处理 100,000 events。"},{"week":"W10","category":"性能","term":"Latency / Response time","chinese":"延迟／响应时间","concept":"单个事件或请求从进入到得到结果的时间。","purpose":"衡量实时性和用户体验。","relation":"可能与 throughput 存在权衡。","example":"交易告警 P95 延迟 200 ms。"},{"week":"W10","category":"扩展性","term":"Elasticity","chinese":"弹性","concept":"资源随负载变化自动增加或减少的能力。","purpose":"在满足性能时控制成本。","relation":"scalability 是能否扩展，elasticity 强调动态自动调整。","example":"白天自动加 worker，夜间缩容。"},{"week":"W10","category":"架构","term":"Scale-agnostic","chinese":"规模无关设计","concept":"应用逻辑尽量不依赖具体节点数和数据位置。","purpose":"让底层扩容而无需改业务代码。","relation":"由 sharding、replication 和分布式框架隐藏复杂性。","example":"同一 Spark 程序从本地切到集群。"},{"week":"W10","category":"架构","term":"Loosely coupled system","chinese":"松耦合系统","concept":"组件通过稳定接口交互，彼此依赖较少。","purpose":"支持独立扩容、替换和故障隔离。","relation":"消息队列常用于解耦。","example":"采集服务与分析服务通过 Kafka 连接。"},{"week":"W10","category":"架构","term":"Separation of compute and storage","chinese":"计算存储分离","concept":"计算节点与持久存储独立扩缩。","purpose":"按不同需求调整算力和容量。","relation":"会增加网络依赖和 availability 考量。","example":"Spark 临时集群读取 S3 数据。"},{"week":"W10","category":"存储","term":"Indexing","chinese":"索引","concept":"创建辅助结构以更快定位满足条件的数据。","purpose":"减少全表扫描。","relation":"提高读性能但占空间并增加写维护成本。","example":"B-tree 加速 customer_id 查询。"},{"week":"W10","category":"存储","term":"Clustering","chinese":"数据聚簇／物理排序","concept":"按某些键让相近记录物理靠近。","purpose":"减少范围查询 I/O。","relation":"与 ML clustering 无关；这里是存储布局。","example":"按日期聚簇日志。"},{"week":"W10","category":"存储","term":"RAID","chinese":"独立磁盘冗余阵列","concept":"把数据条带化或复制到多块磁盘。","purpose":"提高单机存储吞吐或容错。","relation":"不是跨机器数据库 replication 的替代。","example":"RAID 1 镜像两个磁盘。"},{"week":"W10","category":"存储","term":"Row store","chinese":"行式存储","concept":"同一记录的各列连续存放。","purpose":"适合整行点查、插入和 OLTP。","relation":"列式存储更适合扫描少数列的分析。","example":"读取某客户完整资料。"},{"week":"W10","category":"存储","term":"Column store / Columnar storage","chinese":"列式存储","concept":"同一列的值连续存放。","purpose":"减少分析查询 I/O、提高压缩和列向量计算。","relation":"不要与 wide-column database 混淆。","example":"十亿行只读取 sales 列求 AVG。"},{"week":"W10","category":"存储","term":"Pure vs Mixed column organisation","chinese":"纯列／混合列组织","concept":"页面只存一种列值，或在页面中混合若干列块。","purpose":"在扫描效率与重建行成本间取舍。","relation":"都是 column-store 的物理布局选择。","example":"同一 page 只存 amount 列。"},{"week":"W10","category":"存储","term":"Apache Parquet","chinese":"Parquet 列式文件","concept":"支持嵌套类型、压缩和编码的开源列式文件格式。","purpose":"高效保存数据湖分析数据。","relation":"是文件格式，不是数据库或 wide-column store。","example":"Spark 只读取 Parquet 的 date、amount 两列。"},{"week":"W10","category":"存储","term":"Compression / Encoding","chinese":"压缩／编码","concept":"利用重复值和数据规律减少存储与 I/O。","purpose":"列式同类型数据通常更易压缩。","relation":"节省 I/O 可能比解压 CPU 成本更重要。","example":"状态列用字典编码。"},{"week":"W10","category":"存储","term":"Wide-column store","chinese":"宽列数据库","concept":"按 row key、column family 和稀疏列组织的分布式数据库模型。","purpose":"存储超宽、稀疏且可扩展的记录。","relation":"不同于按列连续存放的 columnar analytics format。","example":"HBase / Bigtable。"},{"week":"W10","category":"存储","term":"Column family","chinese":"列族","concept":"wide-column store 中一起组织和存储的一组相关列。","purpose":"定义物理局部性和访问单位。","relation":"列族内部通常按行键组织。","example":"profile:name 与 profile:email 同属 profile family。"},{"week":"W10","category":"分布式数据","term":"Data partitioning / Sharding","chinese":"数据分区／分片","concept":"把原数据的不同子集放到不同磁盘或节点。","purpose":"提高容量和并行度。","relation":"partition 保存不同数据；replica 保存相同数据副本。","example":"按 customer_id 把客户分到 8 个 shards。"},{"week":"W10","category":"分布式数据","term":"Horizontal partitioning","chinese":"水平分区","concept":"按行把表拆成多个 shard。","purpose":"让每个节点处理部分记录。","relation":"所有分区通常保留相同列。","example":"NSW 行与 VIC 行存不同节点。"},{"week":"W10","category":"分布式数据","term":"Vertical partitioning","chinese":"垂直分区","concept":"按列把表拆分并用 key 关联。","purpose":"分离常用列、敏感列或大对象。","relation":"各分区保存不同属性。","example":"基本资料与大照片列分开。"},{"week":"W10","category":"分布式数据","term":"Round-robin partitioning","chinese":"轮询分区","concept":"依次把记录分配到各节点。","purpose":"在无好 key 时获得较均匀记录数。","relation":"不保留范围局部性，按业务 key 查询可能扫全部节点。","example":"第 1 行到节点1、第2行到节点2。"},{"week":"W10","category":"分布式数据","term":"Hash partitioning","chinese":"哈希分区","concept":"对 key 做 hash 决定目标分区。","purpose":"通常获得均匀分布和等值查询定位。","relation":"不利于范围查询。","example":"hash(customer_id)%8。"},{"week":"W10","category":"分布式数据","term":"Range partitioning","chinese":"范围分区","concept":"按 key 值区间分配节点。","purpose":"支持范围查询和顺序扫描。","relation":"容易因热点区间产生 skew。","example":"日期 1–7 日、8–14 日分别存储。"},{"week":"W10","category":"分布式数据","term":"Partition key / Shard key","chinese":"分区键／分片键","concept":"决定记录存到哪个分区的字段。","purpose":"影响负载均衡、查询路由和 join 成本。","relation":"好 key 高基数、分布均匀且匹配访问模式。","example":"customer_id 比 state 更可能均匀。"},{"week":"W10","category":"分布式数据","term":"Data skew / Hotspot","chinese":"数据倾斜／热点","concept":"少数 partition 拥有过多数据或请求。","purpose":"解释为何增加节点仍可能慢。","relation":"坏 partition key 或流行 key 常导致 skew。","example":"50% 订单都属于同一 merchant_id。"},{"week":"W10","category":"分布式数据","term":"Shuffle","chinese":"重分区传输","concept":"为 group/join 等按 key 在节点间重新移动数据。","purpose":"把相同 key 聚到一起。","relation":"网络和磁盘成本高，常是瓶颈。","example":"groupBy(customer_id) 前跨节点发送记录。"},{"week":"W10","category":"复制","term":"Data replication","chinese":"数据复制","concept":"在不同位置保存相同数据的多个副本。","purpose":"提高可用性、读取能力和故障恢复。","relation":"不是 backup；错误也可能被复制。","example":"一个 partition 有 3 个 replicas。"},{"week":"W10","category":"复制","term":"Synchronous / Eager replication","chinese":"同步／急切复制","concept":"原事务提交前更新所需副本。","purpose":"提供更强一致性。","relation":"等待多个节点导致更高写延迟和可用性风险。","example":"两个副本确认后才返回成功。"},{"week":"W10","category":"复制","term":"Asynchronous / Lazy replication","chinese":"异步／延迟复制","concept":"先在一个副本提交，之后传播到其他副本。","purpose":"降低写延迟并提高吞吐。","relation":"secondary 可能 stale，故障时可能丢最后更新。","example":"primary 返回后再 log shipping。"},{"week":"W10","category":"复制","term":"Primary copy / Single leader","chinese":"主副本／单领导者","concept":"所有写入先到唯一 authoritative leader。","purpose":"简化写入排序和冲突控制。","relation":"读取可从 follower，但可能旧。","example":"MongoDB Primary 接收全部 writes。"},{"week":"W10","category":"复制","term":"Multi-leader / Update anywhere","chinese":"多领导者／任意处更新","concept":"多个副本都能接受写入。","purpose":"支持多地区本地写和灵活性。","relation":"并发冲突需要检测与 resolution。","example":"悉尼和伦敦 leader 同时修改记录。"},{"week":"W10","category":"复制","term":"Log shipping","chinese":"日志传送","concept":"把 leader 的变更日志发送给 replicas 重放。","purpose":"实现异步复制。","relation":"传的是变化记录而非每次完整数据集。","example":"MongoDB secondary 应用 oplog。"},{"week":"W10","category":"复制","term":"Conflict resolution","chinese":"冲突解决","concept":"合并多个 leader 对同一数据的并发修改。","purpose":"保证副本最终收敛。","relation":"策略可按版本、时间、业务规则或人工处理。","example":"两个地区同时改用户名时选择版本。"},{"week":"W10","category":"MongoDB","term":"MongoDB sharding","chinese":"MongoDB 分片","concept":"把 collection 按 shard key 分布到多个 shards。","purpose":"水平扩展容量和吞吐。","relation":"每个 shard 通常又是 replica set。","example":"orders collection 按 customer_id 分片。"},{"week":"W10","category":"MongoDB","term":"mongos","chinese":"MongoDB 查询路由器","concept":"根据 shard metadata 把客户端请求路由到目标 shards。","purpose":"隐藏数据分布并合并结果。","relation":"缺少 shard key 可能 scatter-gather。","example":"包含 customer_id 的查询只访问一个 shard。"},{"week":"W10","category":"MongoDB","term":"Config server","chinese":"配置服务器","concept":"保存 MongoDB sharded cluster 的分片元数据。","purpose":"让 mongos 知道 chunk 位于哪里。","relation":"不保存主要业务 collection 数据。","example":"记录 key range→shard 映射。"},{"week":"W10","category":"MongoDB","term":"Shard / Replica set","chinese":"分片／副本集","concept":"shard 保存数据子集；replica set 保存该子集的多个副本。","purpose":"同时实现容量扩展和可用性。","relation":"sharding 与 replication 是正交机制。","example":"Shard A 是三节点 replica set。"},{"week":"W10","category":"MongoDB","term":"Read Preference","chinese":"读取偏好","concept":"控制 MongoDB 读请求发往 primary 还是 secondary。","purpose":"在一致性、延迟和读扩展间取舍。","relation":"读 secondary 可能看到 stale data。","example":"primaryPreferred。"},{"week":"W10","category":"MongoDB","term":"Scatter-gather","chinese":"广播查询","concept":"路由器把查询发到多个或全部 shards 再合并。","purpose":"处理无法按 shard key 定向的查询。","relation":"成本高，良好查询应尽量 targeted。","example":"不带 customer_id 的过滤扫所有 shards。"},{"week":"W10","category":"一致性","term":"Strong consistency","chinese":"强一致性","concept":"读操作返回最近成功写入的值。","purpose":"为金融等场景提供单一最新视图。","relation":"网络分区下常以降低 availability 为代价。","example":"转账后任何节点立即读到新余额。"},{"week":"W10","category":"一致性","term":"High availability","chinese":"高可用性","concept":"系统在故障时仍能响应请求。","purpose":"减少服务中断。","relation":"响应不一定是最新值。","example":"一个节点宕机仍由 replica 提供读服务。"},{"week":"W10","category":"一致性","term":"Partition tolerance","chinese":"分区容错","concept":"网络分裂、节点互不可达时系统仍能按选定策略运行。","purpose":"是分布式系统必须面对的故障条件。","relation":"CAP 中 P 不是平时可随意关闭的功能。","example":"两机房断网。"},{"week":"W10","category":"一致性","term":"CAP theorem","chinese":"CAP 定理","concept":"发生网络分区时，系统不能同时保证强一致响应与所有请求可用。","purpose":"帮助解释分区故障时的设计取舍。","relation":"讨论的是 C/A 在 P 下的选择，不是日常任意选两个。","example":"银行偏 CP，社交计数可偏 AP。"},{"week":"W10","category":"一致性","term":"CP system","chinese":"一致性＋分区容错系统","concept":"分区时拒绝或延迟部分请求以避免返回不一致数据。","purpose":"保护关键正确性。","relation":"牺牲部分 availability。","example":"无法确认最新余额时拒绝转账。"},{"week":"W10","category":"一致性","term":"AP system","chinese":"可用性＋分区容错系统","concept":"分区时继续响应，即使数据暂时不一致。","purpose":"保持服务可用。","relation":"之后需要副本收敛。","example":"点赞数暂时不同但仍可点赞。"},{"week":"W10","category":"一致性","term":"Read-your-writes consistency","chinese":"读己之写一致性","concept":"用户写入后自己的后续读取至少能看到该写入。","purpose":"保证直观会话体验。","relation":"异步 replica 读可能违反它。","example":"换头像后刷新应立即看到新头像。"},{"week":"W10","category":"一致性","term":"Stale read","chinese":"陈旧读取","concept":"从未追上最新写入的副本读到旧值。","purpose":"识别异步复制的一致性风险。","relation":"通过读 primary、等待或 session guarantee 缓解。","example":"伦敦 replica 尚未收到纽约头像更新。"},{"week":"W10","category":"存储系统","term":"HDFS","chinese":"Hadoop 分布式文件系统","concept":"把大文件切成 blocks 并在 DataNodes 间复制的分布式文件系统。","purpose":"为大规模顺序读写与计算提供可靠存储。","relation":"NameNode 管 metadata，DataNode 存实际 blocks。","example":"Spark 从 HDFS 读取日志。"},{"week":"W10","category":"存储系统","term":"NameNode","chinese":"名称节点","concept":"管理 HDFS namespace、权限、block 位置和复制信息。","purpose":"告诉 client 数据块在哪。","relation":"普通读取中不转发全部文件数据。","example":"client 先向 NameNode 请求 block locations。"},{"week":"W10","category":"存储系统","term":"DataNode","chinese":"数据节点","concept":"实际存储和传输 HDFS blocks 的 worker。","purpose":"向 client 提供数据并复制 blocks。","relation":"由 NameNode 管理元数据。","example":"client 从最近 DataNode 读取 block。"},{"week":"W10","category":"存储系统","term":"Block","chinese":"数据块","concept":"HDFS 将大文件切分的固定大粒度存储单位。","purpose":"允许分布、复制和并行读取。","relation":"小文件过多会增加 NameNode metadata 压力。","example":"一个 256MB 文件分成多个 blocks。"},{"week":"W10","category":"存储系统","term":"Data locality","chinese":"数据局部性","concept":"尽量让计算在数据所在或邻近节点执行。","purpose":"减少网络传输并提高吞吐。","relation":"计算存储分离时要权衡远程 I/O。","example":"调度 map task 到保存 block 的 DataNode。"},{"week":"W10","category":"生态","term":"Hadoop","chinese":"Hadoop 生态／MapReduce 实现","concept":"包含 HDFS、YARN 和 MapReduce 等分布式组件。","purpose":"隐藏并行化、容错和数据分布细节。","relation":"Spark/Flink 可运行在 Hadoop 存储与资源层上。","example":"HDFS 存数据，YARN 调度作业。"},{"week":"W10","category":"生态","term":"YARN","chinese":"Yet Another Resource Negotiator","concept":"Hadoop 集群资源管理和作业调度层。","purpose":"给 Spark/Flink 等应用分配容器资源。","relation":"不是存储系统，也不是查询语言。","example":"Spark application 提交到 YARN。"},{"week":"W10","category":"生态","term":"Apache Hive / HiveQL","chinese":"Hive／Hive 查询语言","concept":"在 HDFS 文件上定义关系 schema 并用 SQL 风格查询。","purpose":"把高层查询翻译为分布式作业。","relation":"schema-on-read，早期常转 MapReduce。","example":"HiveQL GROUP BY 统计词频。"},{"week":"W10","category":"计算模型","term":"MapReduce","chinese":"映射归约模型","concept":"用 map 产生 key-value，再经 shuffle/sort 送给 reduce 汇总。","purpose":"在集群上并行处理大数据。","relation":"框架负责分区、调度和容错。","example":"WordCount。"},{"week":"W10","category":"计算模型","term":"Map","chinese":"映射阶段","concept":"对输入记录独立转换并发出中间 key-value。","purpose":"过滤、解析和建立分组键。","relation":"通常高度并行。","example":"每个单词输出 (word,1)。"},{"week":"W10","category":"计算模型","term":"Reduce","chinese":"归约阶段","concept":"接收同 key 的所有值并计算汇总。","purpose":"完成 count、sum 等按键聚合。","relation":"依赖前面的 shuffle/sort。","example":"对 (word,[1,1,1]) 输出 3。"},{"week":"W10","category":"计算模型","term":"Combiner","chinese":"本地合并器","concept":"在 map 端先局部合并中间结果。","purpose":"减少 shuffle 数据量。","relation":"只能用于可安全结合的运算；平均值不能直接平均局部平均。","example":"局部先求 word count。"},{"week":"W10","category":"Spark","term":"Apache Spark","chinese":"Apache Spark","concept":"以内存计算和高层 API 为主的分布式数据处理框架。","purpose":"执行批处理、SQL、ML 和流处理。","relation":"以 RDD 为核心并提供 DataFrame/SQL。","example":"PySpark 聚合 Bitcoin 数据。"},{"week":"W10","category":"Spark","term":"SparkSession","chinese":"Spark 应用入口对象","concept":"负责配置、读写数据和访问 SQL 功能。","purpose":"统一建立 DataFrame 和执行环境。","relation":"本地 local[*] 与集群模式可使用相同 API。","example":"SparkSession.builder.appName(...).getOrCreate()。"},{"week":"W10","category":"Spark","term":"Driver","chinese":"驱动进程","concept":"运行主程序、构建计划并协调 executors。","purpose":"调度 jobs、stages 和 tasks。","relation":"collect() 把数据拉回 driver，可能 OOM。","example":"Notebook Python 进程常是 driver。"},{"week":"W10","category":"Spark","term":"Executor","chinese":"执行器进程","concept":"在 worker 上执行 tasks 并缓存 partitions。","purpose":"完成分布式计算。","relation":"executor 数与 partition 数共同影响并行度。","example":"每个 executor 处理若干 DataFrame partitions。"},{"week":"W10","category":"Spark","term":"RDD","chinese":"弹性分布式数据集","concept":"不可变、可分区、可由 lineage 重建的集合。","purpose":"提供 Spark 核心容错抽象。","relation":"DataFrame 是更高层结构化 API。","example":"textFile(...).flatMap(...)。"},{"week":"W10","category":"Spark","term":"DataFrame","chinese":"带命名列的数据集","concept":"具有 schema，并用高层关系操作表达计算。","purpose":"让 Catalyst 优化查询并自动并行。","relation":"比手写 RDD 更适合结构化数据。","example":"df.groupBy('year').avg('volume')。"},{"week":"W10","category":"Spark","term":"Dataset API","chinese":"类型化数据集 API","concept":"结合对象类型安全与 Spark 优化的高层 API。","purpose":"在 Scala/Java 中提供编译期类型帮助。","relation":"Python 主要使用 DataFrame，不提供同样的 typed Dataset。","example":"Dataset[Person]。"},{"week":"W10","category":"Spark","term":"Transformation","chinese":"转换操作","concept":"返回新 RDD/DataFrame 的惰性操作。","purpose":"构建执行 DAG。","relation":"不会立即运行，直到 action 触发。","example":"select、filter、groupBy。"},{"week":"W10","category":"Spark","term":"Action","chinese":"动作操作","concept":"要求结果或写出数据并触发执行。","purpose":"启动 Spark job。","relation":"collect/show/count/write 都会执行计划。","example":"df.count()。"},{"week":"W10","category":"Spark","term":"Lazy evaluation","chinese":"惰性求值","concept":"先记录 transformations，遇到 action 才真正执行。","purpose":"让优化器重排、合并操作并减少工作。","relation":"看到代码调用 filter 不代表已经扫描数据。","example":"df.filter(...).select(...); df.show() 时运行。"},{"week":"W10","category":"Spark","term":"DAG","chinese":"有向无环图","concept":"表示 transformations 依赖关系的执行计划图。","purpose":"帮助切分 stages、调度和容错。","relation":"wide dependency 常形成 stage 边界。","example":"Spark UI 显示 job DAG。"},{"week":"W10","category":"Spark","term":"Narrow vs Wide dependency","chinese":"窄依赖／宽依赖","concept":"窄依赖的子 partition 只依赖少量父 partition；宽依赖跨多分区取数。","purpose":"判断是否可流水线及是否发生 shuffle。","relation":"map/filter 通常窄；groupByKey 通常宽。","example":"reduceByKey 会触发按 key 重分区。"},{"week":"W10","category":"Spark","term":"Cache / Persist","chinese":"缓存／持久化中间结果","concept":"把重复使用的分布式数据保留在内存或磁盘。","purpose":"避免反复计算 lineage。","relation":"缓存也占资源，且第一次 action 才物化。","example":"df.cache(); df.count()。"},{"week":"W10","category":"Spark","term":"collect() / toPandas()","chinese":"收集到驱动端","concept":"把分布式结果全部复制到 driver 内存。","purpose":"只适合小结果的本地查看或绘图。","relation":"对大数据使用会造成 driver OOM。","example":"先 groupBy 聚合成 12 行再 toPandas。"},{"week":"W10","category":"Spark","term":"Temporary view","chinese":"临时视图","concept":"把 DataFrame 注册为当前 SparkSession 内可用的 SQL 名称。","purpose":"让 DataFrame 与 spark.sql 互操作。","relation":"会话结束后不持久保存。","example":"createOrReplaceTempView('bitcoin')。"},{"week":"W10","category":"Spark","term":"Catalyst Optimizer","chinese":"Catalyst 查询优化器","concept":"Spark SQL 把表达式转换并优化 logical/physical plan 的框架。","purpose":"执行谓词下推、列裁剪等优化。","relation":"依赖结构化 DataFrame/SQL 信息。","example":"explain() 查看优化计划。"},{"week":"W10","category":"Spark","term":"Cost-Based Optimizer (CBO)","chinese":"基于成本优化器","concept":"利用统计信息估算候选计划成本。","purpose":"选择 join 顺序和策略。","relation":"统计信息陈旧会降低选择质量。","example":"选择 broadcast join 或 sort-merge join。"},{"week":"W10","category":"Spark","term":"Adaptive Query Execution (AQE)","chinese":"自适应查询执行","concept":"运行时根据实际数据统计调整物理计划。","purpose":"处理估算误差、shuffle partition 和 skew。","relation":"是在执行阶段动态优化。","example":"运行时合并过小 shuffle partitions。"},{"week":"W10","category":"Spark","term":"UDF (User-Defined Function)","chinese":"用户自定义函数","concept":"用户编写并在数据操作中调用的函数。","purpose":"表达内建函数没有的业务逻辑。","relation":"可能阻碍优化并有序列化开销，优先内建函数。","example":"自定义文本评分函数。"},{"week":"W10","category":"Spark","term":"local[*]","chinese":"本地全核模式","concept":"在单个 JVM/电脑上用所有本地 CPU 核运行 Spark。","purpose":"验证 API、逻辑和 notebook。","relation":"不代表真实多节点，也不能证明网络扩展性。","example":"SparkSession.master('local[*]')。"},{"week":"W10","category":"Flink","term":"Flink DataSet API","chinese":"Flink 批数据 API","concept":"对有界集合执行批处理转换的 API。","purpose":"表达批量 join、group 和 iteration。","relation":"课程中与 DataStream API 区分。","example":"env.from_collection(...).group_by(...)。"},{"week":"W10","category":"Flink","term":"Flink DataStream API","chinese":"Flink 流数据 API","concept":"对有界或无界事件流执行状态、窗口和 event-time 操作。","purpose":"实现原生连续流处理。","relation":"位于 Flink runtime 之上。","example":"stream.key_by(...).window(...)。"},{"week":"W10","category":"Flink","term":"Table API / SQL","chinese":"Flink 表 API／SQL","concept":"在流和批数据上使用关系表达式。","purpose":"让优化器生成 dataflow plan。","relation":"动态表可表达持续更新结果。","example":"SELECT key,COUNT(*) FROM stream GROUP BY key。"},{"week":"W10","category":"Flink","term":"env.execute()","chinese":"Flink 执行触发","concept":"提交并启动此前构建的执行计划。","purpose":"把 lazy plan 变成运行中的 job。","relation":"某些 print/collect 调用也可能立即触发。","example":"定义 pipeline 后调用 env.execute()。"}];
